import axios from 'axios';

// Create separate axios instances for each service
const createApiInstance = (baseUrl) => {
  const instance = axios.create({
    baseURL: `${baseUrl}/api/v1`,
    headers: { 'Content-Type': 'application/json' },
  });

  // Attach JWT token to all requests
  instance.interceptors.request.use((config) => {
    const token = localStorage.getItem('medibook_token');
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
  });

  return instance;
};

const appointmentApi = createApiInstance(process.env.REACT_APP_API_URL || 'http://localhost:5169');
const authApi = createApiInstance(process.env.REACT_APP_AUTH_SERVICE_URL || 'http://localhost:5036');
const providerApi = createApiInstance(process.env.REACT_APP_PROVIDER_SERVICE_URL || 'http://localhost:5268');
const availabilityApi = createApiInstance(process.env.REACT_APP_AVAILABILITY_SERVICE_URL || 'http://localhost:5211');
const paymentApi = createApiInstance(process.env.REACT_APP_PAYMENT_SERVICE_URL || 'http://localhost:5289');
const notificationApi = createApiInstance(process.env.REACT_APP_NOTIFICATION_SERVICE_URL || 'http://localhost:5134');
const recordApi = createApiInstance(process.env.REACT_APP_RECORD_SERVICE_URL || 'http://localhost:5174');
const reviewApi = createApiInstance(process.env.REACT_APP_REVIEW_SERVICE_URL || 'http://localhost:5071');

// Appointment endpoints
export const appointmentService = {
  book: (data) => appointmentApi.post('/appointments', data),
  getById: (id) => appointmentApi.get(`/appointments/${id}`),
  getByPatient: (patientId) => appointmentApi.get(`/appointments/patient/${patientId}`),
  getUpcomingByPatient: (patientId) => appointmentApi.get(`/appointments/patient/${patientId}/upcoming`),
  getByProvider: (providerId) => appointmentApi.get(`/appointments/provider/${providerId}`),
  getByProviderAndDate: (providerId, date) =>
    appointmentApi.get(`/appointments/provider/${providerId}/date/${date}`),
  cancel: (id) => appointmentApi.put(`/appointments/${id}/cancel`),
  reschedule: (id, data) => appointmentApi.put(`/appointments/${id}/reschedule`, data),
  complete: (id) => appointmentApi.put(`/appointments/${id}/complete`),
  updateStatus: (id, status) => appointmentApi.put(`/appointments/${id}/status`, JSON.stringify(status)),
  getProviderCount: (providerId) => appointmentApi.get(`/appointments/provider/${providerId}/count`),
};

// Auth endpoints
export const authService = {
  register: (data) => authApi.post('/auth/register', data),
  login: (data) => authApi.post('/auth/login', data),
  logout: () => authApi.post('/auth/logout'),
  refreshToken: (data) => authApi.post('/auth/refresh', data),
  getProfile: () => authApi.get('/auth/profile'),
  updateProfile: (data) => authApi.put('/auth/profile', data),
  changePassword: (data) => authApi.put('/auth/password', data),
  deactivateAccount: () => authApi.delete('/auth/deactivate'),
};

// Provider endpoints
export const providerService = {
  register: (data) => providerApi.post('/providers', data),
  getById: (id) => providerApi.get(`/providers/${id}`),
  getBySpecialization: (specialization) => providerApi.get(`/providers/specialization/${specialization}`),
  search: (term) => providerApi.get('/providers/search', { params: { term } }),
  getAll: () => providerApi.get('/providers'),
  update: (id, data) => providerApi.put(`/providers/${id}`, data),
  verify: (id) => providerApi.put(`/providers/${id}/verify`),
  setAvailability: (id, data) => providerApi.put(`/providers/${id}/availability`, data),
  delete: (id) => providerApi.delete(`/providers/${id}`),
  updateRating: (id, rating) => providerApi.put(`/providers/${id}/rating`, rating),
};

// Availability/Slot endpoints
export const slotService = {
  add: (data) => availabilityApi.post('/slots', data),
  addBulk: (data) => availabilityApi.post('/slots/bulk', data),
  generateRecurring: (data) => availabilityApi.post('/slots/recurring', data),
  getByProvider: (providerId) => availabilityApi.get(`/slots/provider/${providerId}`),
  getAvailable: (providerId, date) => availabilityApi.get(`/slots/provider/${providerId}/available`, { params: { date } }),
  getById: (id) => availabilityApi.get(`/slots/${id}`),
  book: (id) => availabilityApi.put(`/slots/${id}/book`),
  block: (id, data) => availabilityApi.put(`/slots/${id}/block`, data),
  unblock: (id) => availabilityApi.put(`/slots/${id}/unblock`),
  update: (id, data) => availabilityApi.put(`/slots/${id}`, data),
  delete: (id) => availabilityApi.delete(`/slots/${id}`),
};

// Payment endpoints
export const paymentService = {
  process: (data) => paymentApi.post('/payments/process', data),
  getByAppointment: (appointmentId) => paymentApi.get(`/payments/appointment/${appointmentId}`),
  getByPatient: (patientId) => paymentApi.get(`/payments/patient/${patientId}`),
  getHistory: (patientId) => paymentApi.get(`/payments/patient/${patientId}/history`),
  refund: (paymentId, data) => paymentApi.post(`/payments/${paymentId}/refund`, data),
  getStatus: (paymentId) => paymentApi.get(`/payments/${paymentId}/status`),
  updateStatus: (paymentId, status) => paymentApi.put(`/payments/${paymentId}/status`, status),
  generateInvoice: (paymentId) => paymentApi.get(`/payments/${paymentId}/invoice`, { responseType: 'blob' }),
  getTotalRevenue: () => paymentApi.get('/payments/revenue/total'),
};

// Notification endpoints
export const notificationService = {
  send: (data) => notificationApi.post('/notifications/send', data),
  sendBulk: (data) => notificationApi.post('/notifications/sendBulk', data),
  getByRecipient: (recipientId) => notificationApi.get(`/notifications/recipient/${recipientId}`),
  markAsRead: (notificationId) => notificationApi.put(`/notifications/${notificationId}/markAsRead`),
  markAllRead: (recipientId) => notificationApi.put(`/notifications/recipient/${recipientId}/markAllRead`),
  getUnreadCount: (recipientId) => notificationApi.get(`/notifications/recipient/${recipientId}/unreadCount`),
  delete: (notificationId) => notificationApi.delete(`/notifications/${notificationId}`),
  getAll: () => notificationApi.get('/notifications/all'),
};

// Medical Record endpoints
export const recordService = {
  create: (data) => recordApi.post('/records', data),
  getByAppointment: (appointmentId) => recordApi.get(`/records/appointment/${appointmentId}`),
  getByPatient: (patientId) => recordApi.get(`/records/patient/${patientId}`),
  getByProvider: (providerId) => recordApi.get(`/records/provider/${providerId}`),
  getById: (recordId) => recordApi.get(`/records/${recordId}`),
  update: (recordId, data) => recordApi.put(`/records/${recordId}`, data),
  getFollowUpRecords: (followUpDate) => recordApi.get(`/records/followUps/${followUpDate}`),
  getCount: (patientId) => recordApi.get(`/records/patient/${patientId}/count`),
  delete: (recordId) => recordApi.delete(`/records/${recordId}`),
  getAll: () => recordApi.get('/records/all'),
};

// Review endpoints
export const reviewService = {
  add: (data) => reviewApi.post('/reviews', data),
  getByProvider: (providerId) => reviewApi.get(`/reviews/provider/${providerId}`),
  getByPatient: (patientId) => reviewApi.get(`/reviews/patient/${patientId}`),
  getByAppointment: (appointmentId) => reviewApi.get(`/reviews/appointment/${appointmentId}`),
  update: (reviewId, data) => reviewApi.put(`/reviews/${reviewId}`, data),
  delete: (reviewId) => reviewApi.delete(`/reviews/${reviewId}`),
  getAvgRating: (providerId) => reviewApi.get(`/reviews/provider/${providerId}/avgRating`),
  getCount: (providerId) => reviewApi.get(`/reviews/provider/${providerId}/count`),
  getAll: () => reviewApi.get('/reviews/all'),
};

export default appointmentApi;
